function visible(){if(visibleCache)return visibleCache;visibleCache=nodes.filter(n=>{const category=normalizeCategory(n.type,n.ore),hay=(n.name+' '+n.ore+' '+n.cluster+' '+categoryInfo(category).label).toLowerCase(),inRegion=!focusedRegion||focusedRegion.clusters.some(cluster=>cluster.name===n.cluster);return(!focusedCluster||n.cluster===focusedCluster.name)&&inRegion&&(filter==='all'||category===filter)&&(!activeResource||nodeResources(n).includes(activeResource))&&hay.includes(query)});return visibleCache}
function renderSectors(){const picker=document.getElementById('sectorPicker');picker.innerHTML='<option value="">All sectors</option>'+regions.map(region=>`<optgroup label="${escapeHtml(regionLabel(region).toUpperCase())} · ${region.clusters.length} ${region.clusters.length===1?'cluster':'clusters'}">${region.clusters.slice().sort((a,b)=>clusterLabel(a).localeCompare(clusterLabel(b))).map(cluster=>`<option value="${escapeHtml(cluster.name)}">${escapeHtml(clusterLabel(cluster))} (${nodes.filter(n=>n.cluster===cluster.name).length})</option>`).join('')}</optgroup>`).join('');picker.value=focusedCluster?.name||'';picker.onchange=()=>picker.value?focusSector(picker.value):returnToMainMap();const count=document.getElementById('regionCount');if(count)count.textContent=String(regions.length).padStart(2,'0')}
function showEmptySelection(){document.getElementById('selectedCard').innerHTML='<div class="empty-state"><span>◎</span><strong>Select a node</strong><p>Choose a location from the atlas or map to inspect its coordinates.</p></div>'}


function focusRegion(name){clearRegionHover();focusedRegion=regions.find(region=>region.name===name)||null;focusedCluster=null;selected=null;zoom=1;panX=0;panY=0;document.getElementById('zoomLabel').textContent='100%';document.getElementById('zoomSlider').value=100;const back=document.getElementById('backToMap');back.textContent='← Main map';back.style.display=focusedRegion?'inline-block':'none';renderSectors();renderList();renderRegionDetails(focusedRegion);draw()}
function focusSector(name){clearRegionHover();focusedCluster=clusters.find(cluster=>cluster.name===name)||null;focusedRegion=regions.find(region=>region.clusters.includes(focusedCluster))||null;selected=null;zoom=1;panX=0;panY=0;document.getElementById('zoomLabel').textContent='100%';document.getElementById('zoomSlider').value=100;const back=document.getElementById('backToMap');back.textContent=overviewMode==='clusters'?'← All clusters':focusedRegion?`← ${regionLabel(focusedRegion)}`:'← Main map';back.style.display='inline-block';renderSectors();renderList();renderClusterDetails(focusedCluster);draw()}
function line(a,b,color){ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}
function skyRotate(parallax=1){const cosYaw=Math.cos(yaw*parallax),sinYaw=Math.sin(yaw*parallax),cosPitch=Math.cos(pitch*parallax),sinPitch=Math.sin(pitch*parallax);return point=>{const x=cosYaw*point.x-sinYaw*point.z,depth0=sinYaw*point.x+cosYaw*point.z;return{x,y:cosPitch*point.y-sinPitch*depth0,depth:sinPitch*point.y+cosPitch*depth0}}}
function skyColor(tint){return tint>.8?'229,248,179':tint>.48?'116,222,228':'201,224,232'}
function drawSkyGlow(point,w,h,source,parallax){const rotated=skyRotate(parallax)(point);if(rotated.depth<-.28)return;const x=w*.5+rotated.x*w*.67,y=h*.5-rotated.y*h*.67,r=Math.min(w,h)*source.size*(.82+rotated.depth*.38),alpha=source.alpha*(.74+rotated.depth*.3);ctx.save();ctx.translate(x,y);ctx.rotate((source.tilt||0)+yaw*parallax*.22);ctx.scale(source.stretch||1,1);const gradient=ctx.createRadialGradient(0,0,0,0,0,r);gradient.addColorStop(0,'rgba('+source.color+','+alpha+')');gradient.addColorStop(.18,'rgba('+source.color+','+(alpha*.78)+')');gradient.addColorStop(.5,'rgba('+source.color+','+(alpha*.3)+')');gradient.addColorStop(.78,'rgba('+source.color+','+(alpha*.08)+')');gradient.addColorStop(1,'rgba('+source.color+',0)');ctx.fillStyle=gradient;ctx.fillRect(-r,-r,r*2,r*2);ctx.restore()}
function drawSkySpecks(collection,w,h,parallax,band=false){const rotate=skyRotate(parallax);collection.forEach(speck=>{const point=rotate(speck);if(point.depth<-.12)return;const x=w*.5+point.x*w*(.49+.09*point.depth),y=h*.5-point.y*h*(.49+.09*point.depth),size=speck.size*(.68+point.depth*.42);if(x<-4||x>w+4||y<-4||y>h+4)return;const color=skyColor(speck.tint),alpha=speck.alpha*(.52+point.depth*.48);ctx.fillStyle='rgba('+color+','+alpha+')';if(size<1.25)ctx.fillRect(x-size*.5,y-size*.5,size,size);else{ctx.beginPath();ctx.arc(x,y,size,0,Math.PI*2);ctx.fill()}if(!band&&size>1.55&&alpha>.32){ctx.strokeStyle='rgba('+color+','+(alpha*.38)+')';ctx.lineWidth=.65;ctx.beginPath();ctx.moveTo(x-size*2.6,y);ctx.lineTo(x+size*2.6,y);ctx.moveTo(x,y-size*2.6);ctx.lineTo(x,y+size*2.6);ctx.stroke()}})}
function drawSkyDust(collection,w,h,parallax){const rotate=skyRotate(parallax);collection.forEach(dust=>{const point=rotate(dust);if(point.depth<-.08)return;const x=w*.5+point.x*w*(.5+.09*point.depth),y=h*.5-point.y*h*(.5+.09*point.depth);if(x<-3||x>w+3||y<-3||y>h+3)return;const color=dust.tint>.55?'91,183,191':'114,142,166';ctx.fillStyle='rgba('+color+','+(dust.alpha*(.42+point.depth*.48))+')';ctx.fillRect(x,y,dust.size,dust.size)})}
function stars(w,h){ctx.save();ctx.globalCompositeOperation='screen';skyNebulae.forEach(nebula=>drawSkyGlow(nebula,w,h,nebula,.56));skyBandWisps.forEach(wisp=>drawSkyGlow(wisp,w,h,wisp,.72));drawSkySpecks(backgroundStars,w,h,.78);drawSkySpecks(skyBandStars,w,h,.9,true);drawSkyDust(skyBandDust,w,h,1.04);drawSkyDust(skyDust,w,h,1.17);ctx.restore()}

function drawMapMarker(p,marker,size,color){const s=Math.max(2,size),style=markerType(marker);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=color;ctx.strokeStyle=colorWithAlpha(color,.96);ctx.lineWidth=Math.max(.7,s*.18);ctx.setLineDash([]);if(style==='home'){ctx.beginPath();ctx.moveTo(-s,-s*.08);ctx.lineTo(0,-s);ctx.lineTo(s,-s*.08);ctx.lineTo(s,s*.8);ctx.lineTo(-s,s*.8);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#071017';ctx.fillRect(-s*.2,s*.25,s*.4,s*.55)}else if(style==='station'){ctx.beginPath();for(let i=0;i<6;i++){const angle=-Math.PI/2+i*Math.PI/3,x=Math.cos(angle)*s,y=Math.sin(angle)*s;i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#071017';ctx.beginPath();ctx.arc(0,0,s*.3,0,Math.PI*2);ctx.fill()}else if(style==='asteroid'){ctx.beginPath();[[-.95,-.22],[-.48,-.92],[.48,-.73],[.98,-.12],[.62,.77],[-.2,.98],[-.88,.48]].forEach(([x,y],index)=>index?ctx.lineTo(x*s,y*s):ctx.moveTo(x*s,y*s));ctx.closePath();ctx.fill();ctx.stroke()}else if(style==='danger'){ctx.beginPath();ctx.moveTo(0,-s);ctx.lineTo(s*.95,s*.82);ctx.lineTo(-s*.95,s*.82);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#071017';ctx.fillRect(-s*.12,-s*.4,s*.24,s*.62);ctx.beginPath();ctx.arc(0,s*.48,s*.15,0,Math.PI*2);ctx.fill()}else{ctx.beginPath();ctx.arc(0,0,s,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawCluster(c){const color=clusterColor(c),points=[];for(let i=0;i<=48;i++){const angle=(i/48)*Math.PI*2;points.push(project(c.x+Math.cos(angle)*c.r,c.y,c.z+Math.sin(angle)*c.r))}ctx.save();ctx.strokeStyle=colorWithAlpha(color,.3);ctx.setLineDash([4,7]);ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.restore()}
function drawRegion(region,active=false){const color=regionColor(region),segments=active?48:32,points=[];for(let i=0;i<=segments;i++){const angle=(i/segments)*Math.PI*2;points.push(project(region.center.x+Math.cos(angle)*region.r,region.center.y,region.center.z+Math.sin(angle)*region.r))}ctx.save();ctx.strokeStyle=colorWithAlpha(color,active ? .42 : .14);ctx.lineWidth=active?1.3:1;ctx.setLineDash(active?[7,6]:[3,9]);ctx.beginPath();points.forEach((p,index)=>index?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();ctx.restore()}



function drawCurrentPosition(){if(!currentPosition)return;const p=project(...Object.values(world(currentPosition)));if(p.x<-45||p.x>canvas.clientWidth+45||p.y<-45||p.y>canvas.clientHeight+45)return;ctx.save();ctx.shadowColor='#f08bd2';ctx.shadowBlur=25;ctx.fillStyle='#f08bd2';ctx.beginPath();ctx.moveTo(p.x,p.y-8);ctx.lineTo(p.x+8,p.y);ctx.lineTo(p.x,p.y+8);ctx.lineTo(p.x-8,p.y);ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='rgba(255,207,240,.92)';ctx.setLineDash([2,3]);ctx.beginPath();ctx.arc(p.x,p.y,18,0,Math.PI*2);ctx.stroke();ctx.font='10px DM Mono';ctx.fillStyle='#ffe0f3';ctx.shadowColor='#071017';ctx.shadowBlur=4;ctx.fillText('CURRENT · '+currentPosition.name,p.x+12,p.y-12);ctx.restore()}
function niceDistance(value){const magnitude=10**Math.floor(Math.log10(value||1)),unit=value/magnitude;return(unit>=5?5:unit>=2?2:1)*magnitude}
function updateScale(){const worldWidth=canvas.clientWidth/(Math.min(canvas.clientWidth,canvas.clientHeight)/(projectionExtent*2));const distance=niceDistance(worldWidth/(5*zoom*mapVisualScale()));document.getElementById('mapScale').textContent=(distance>=1000?(distance/1000).toLocaleString()+' M km':distance.toLocaleString()+' km')}
function formatDistance(value){const distance=value/mapVisualScale();return distance>=1000?(distance/1000).toLocaleString(undefined,{maximumFractionDigits:1})+'M km':Math.round(distance).toLocaleString()+' km'}
function updateMapMode(){const sector=focusedCluster;if(sector){document.getElementById('mapEyebrow').textContent=`${focusedRegion?.kind?.toUpperCase()||'UNASSIGNED'} / SECTOR`;document.getElementById('mapTitle').textContent=`${overviewMode==='clusters'?'All clusters':focusedRegion?regionLabel(focusedRegion):'Unassigned'} · ${clusterLabel(sector)}`;document.getElementById('mapHint').textContent='Select a GPS signal to inspect it · Use the return button to go back';document.getElementById('visibleLabel').textContent='GPS SIGNALS'}else if(focusedRegion){document.getElementById('mapEyebrow').textContent=`${focusedRegion.kind.toUpperCase()} OVERVIEW`;document.getElementById('mapTitle').textContent=regionLabel(focusedRegion);document.getElementById('mapHint').textContent='Select a cluster to inspect its GPS signals';document.getElementById('visibleLabel').textContent='VISIBLE CLUSTERS'}else if(overviewMode==='clusters'){document.getElementById('mapEyebrow').textContent='CLUSTER OVERVIEW';document.getElementById('mapTitle').textContent='All clusters';document.getElementById('mapHint').textContent='Select a cluster to inspect its GPS signals';document.getElementById('visibleLabel').textContent='VISIBLE CLUSTERS'}else{document.getElementById('mapEyebrow').textContent='REGION OVERVIEW';document.getElementById('mapTitle').textContent='Known space';document.getElementById('mapHint').textContent='Select a region to inspect its clusters';document.getElementById('visibleLabel').textContent='VISIBLE REGIONS'}overviewToggle.textContent=overviewMode==='regions'?'◈ All clusters':'◌ Region view'}


function gpsString(n){const color='#FF'+nodeColor(n).slice(1);return`GPS:${n.name}:${n.x}:${n.y}:${n.z}:${color}:${n.note||''}:`}
async function copyGps(n){const text=gpsString(n),button=document.getElementById('copySelected');try{await navigator.clipboard.writeText(text)}catch{const field=document.createElement('textarea');field.value=text;field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();document.execCommand('copy');field.remove()}button.textContent='✓ GPS copied';button.classList.add('copied');setTimeout(()=>{if(document.getElementById('copySelected')===button){button.textContent='⧉ Copy GPS';button.classList.remove('copied')}},1600)}


document.getElementById('closeEditModal').onclick=()=>document.getElementById('editModal').classList.add('hidden');document.getElementById('editForm').onsubmit=async e=>{e.preventDefault();if(!selected)return;const f=new FormData(e.target),gps=parseGps(f.get('gps')),error=document.getElementById('editError');if(!gps){error.textContent='GPS format not recognized. Use GPS:Name:X:Y:Z:#COLOR:Description:';return}const type=normalizeCategory(f.get('type'),selected.ore),color=safeColor(f.get('color'),nodeColor(selected)),visibility=f.get('visibility')||selected.visibility||'user',updated={name:gps.name,type,x:gps.x,y:gps.y,z:gps.z,ore:type==='asteroid'?(selected.ore||'Unknown'):'—',note:f.get('description')||gps.description||'Edited GPS entry.',visibility,color};try{if(document.getElementById('datasetStatus').textContent==='MYSQL CONNECTED'){const response=await fetch('http://127.0.0.1:8765/api/update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:selected.id,name:updated.name,x:updated.x,y:updated.y,z:updated.z,location_type:updated.type,description:updated.note,visibility})});const result=await response.json();if(!response.ok||result.error)throw new Error(result.error||'Could not save to MySQL')}else await saveEntityVisibility('gps',selected.id,visibility);gpsColorSettings[String(selected.id)]={color};if(!saveGpsColorSettings())throw new Error('Your browser could not save the GPS color.');Object.assign(selected,updated);document.getElementById('editModal').classList.add('hidden');select(selected.id)}catch(err){error.textContent=err.message}};
const regionModal=document.getElementById('regionModal');document.getElementById('closeRegionModal').onclick=()=>regionModal.classList.add('hidden');document.getElementById('regionForm').onsubmit=async e=>{e.preventDefault();if(!editingRegion)return;const form=new FormData(e.target),name=String(form.get('name')||'').trim(),color=safeColor(form.get('color'),regionColor(editingRegion)),description=String(form.get('description')||'').trim(),visibility=form.get('visibility')||'user',error=document.getElementById('regionError');if(!name){error.textContent='Region name is required.';return}try{await saveEntityVisibility('region',editingRegion.key,visibility)}catch(err){error.textContent=err.message;return}regionSettings[editingRegion.key]={name,description,color};if(!saveRegionSettings()){error.textContent='Your browser could not save region details.';return}editingRegion.name=name;editingRegion.description=description;editingRegion.color=color;editingRegion.visibility=visibility;editingRegion.clusters.forEach(cluster=>cluster.region=name);regionModal.classList.add('hidden');renderSectors();renderRegionDetails(editingRegion);if(focusedCluster)document.getElementById('backToMap').textContent=`← ${regionLabel(editingRegion)}`;draw()};
const clusterModal=document.getElementById('clusterModal');document.getElementById('closeClusterModal').onclick=()=>clusterModal.classList.add('hidden');document.getElementById('clusterForm').onsubmit=async e=>{e.preventDefault();if(!editingCluster)return;const form=new FormData(e.target),name=String(form.get('name')||'').trim(),color=safeColor(form.get('color'),clusterColor(editingCluster)),description=String(form.get('description')||'').trim(),visibility=form.get('visibility')||'user',error=document.getElementById('clusterError');if(!name){error.textContent='Cluster name is required.';return}try{await saveEntityVisibility('cluster',editingCluster.name,visibility)}catch(err){error.textContent=err.message;return}clusterSettings[editingCluster.name]={name,description,color};if(!saveClusterSettings()){error.textContent='Your browser could not save cluster details.';return}editingCluster.displayName=name;editingCluster.description=description;editingCluster.color=color;editingCluster.visibility=visibility;clusterModal.classList.add('hidden');renderSectors();renderClusterDetails(editingCluster);draw()};
function deleteSelected(id){const n=nodes.find(item=>item.id===id);if(!n)return;if(!window.confirm(`Delete GPS marker “${n.name}”?`))return;const index=nodes.findIndex(item=>item.id===id);nodes.splice(index,1);favoriteIds.delete(String(id));saveFavorites();if(measureOrigin&&measureOrigin.id===id)measureOrigin=null;selected=null;document.getElementById('selectedCard').innerHTML='<div class="empty-state"><span>◎</span><strong>Select a node</strong><p>Choose a location from the atlas or map to inspect its coordinates.</p></div>';renderList();draw()}
function parseGps(text){const parts=text.trim().split(':');if(parts.length<6||parts[0].toUpperCase()!=='GPS')return null;const x=Number(parts[2]),y=Number(parts[3]),z=Number(parts[4]);if(!parts[1]||![x,y,z].every(Number.isFinite))return null;return{name:parts[1],x,y,z,description:parts.slice(6).join(':').trim()}}
document.getElementById('search').oninput=e=>{query=e.target.value.toLowerCase();renderList();draw()};document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;renderList();draw()});
