function showClusterTooltip(cluster,x,y){const signalNames=clusterNodes(cluster).map(node=>node.name).filter((name,index,all)=>all.indexOf(name)===index).sort((a,b)=>a.localeCompare(b)),listed=signalNames.slice(0,4).map(escapeHtml).join(' · ')+(signalNames.length>4?` · +${signalNames.length-4} more`:''),key='cluster:'+cluster.name;if(mapTooltip.dataset.target!==key){mapTooltip.dataset.target=key;mapTooltip.innerHTML=`<span>CLUSTER SIGNAL</span><strong>${escapeHtml(clusterLabel(cluster))}</strong><div class="tooltip-clusters"><span>${signalNames.length} ${signalNames.length===1?'GPS SIGNAL':'GPS SIGNALS'}</span><b>${listed||'No visible GPS signals'}</b></div><p>${escapeHtml(focusedRegion?regionLabel(focusedRegion):'Current')}</p>`}positionMapTooltip(x,y)}



canvas.onpointerdown=e=>{if(e.button!==0&&e.button!==1)return;if(e.button===1)e.preventDefault();dragging=true;pointerMoved=false;activeButton=e.button;last={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!dragging){updateRegionHover(e);return}clearRegionHover();const dx=e.clientX-last.x,dy=e.clientY-last.y;if(Math.abs(e.clientX-last.x)+Math.abs(e.clientY-last.y)>4)pointerMoved=true;if(activeButton===1){panX+=dx;panY+=dy}else{yaw+=dx*.006;pitch-=dy*.006;pitch=Math.max(-1.1,Math.min(1.1,pitch))}last={x:e.clientX,y:e.clientY};draw()};canvas.onpointerup=e=>{if(!pointerMoved&&activeButton===0)handleMapClick(e);dragging=false;activeButton=0};canvas.onpointercancel=()=>{dragging=false;activeButton=0};canvas.onpointerleave=()=>{if(clearRegionHover())draw()};canvas.onauxclick=e=>e.preventDefault();canvas.onwheel=e=>{e.preventDefault();setZoom(zoom*(e.deltaY>0?.86:1.16))};
const setZoom=value=>{zoom=Math.max(.2,Math.min(5,Number(value)));document.getElementById('zoomLabel').textContent=Math.round(zoom*100)+'%';document.getElementById('zoomSlider').value=Math.round(zoom*100);draw()};document.getElementById('zoomSlider').oninput=e=>setZoom(e.target.value/100);document.getElementById('zoomIn').onclick=()=>setZoom(zoom*1.2);document.getElementById('zoomOut').onclick=()=>setZoom(zoom*.84);const centerView=()=>{yaw=-.48;pitch=.25;panX=0;panY=0;setZoom(1)};const returnToMainMap=()=>{clearRegionHover();focusedRegion=null;focusedCluster=null;selected=null;yaw=-.48;pitch=.25;panX=0;panY=0;zoom=1;document.getElementById('zoomLabel').textContent='100%';document.getElementById('zoomSlider').value=100;document.getElementById('backToMap').style.display='none';document.getElementById('editRegion').style.display='none';renderSectors();renderList();showEmptySelection();draw()};const setOverviewMode=mode=>{overviewMode=mode==='clusters'?'clusters':'regions';returnToMainMap()};const returnToRegionMap=()=>{if(!focusedRegion||overviewMode==='clusters'){returnToMainMap();return}clearRegionHover();focusedCluster=null;selected=null;yaw=-.48;pitch=.25;panX=0;panY=0;zoom=1;document.getElementById('zoomLabel').textContent='100%';document.getElementById('zoomSlider').value=100;const back=document.getElementById('backToMap');back.textContent='← Main map';back.style.display='inline-block';document.getElementById('editRegion').style.display='inline-block';renderSectors();renderList();renderRegionDetails(focusedRegion);draw()};document.getElementById('centerView').onclick=centerView;document.getElementById('resetView').onclick=returnToMainMap;document.getElementById('backToMap').onclick=()=>focusedCluster?returnToRegionMap():returnToMainMap();document.getElementById('editRegion').onclick=()=>{if(focusedRegion)openRegionEditor(focusedRegion)};
const modal=document.getElementById('modal');document.getElementById('addLocation').onclick=()=>modal.classList.remove('hidden');document.getElementById('closeModal').onclick=()=>modal.classList.add('hidden');document.getElementById('locationForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),gps=parseGps(f.get('gps')),error=document.getElementById('formError');if(!gps){error.textContent='GPS format not recognized. Use GPS:Name:X:Y:Z:#COLOR:Description:';return}const type=normalizeCategory(f.get('type'));error.textContent='';nodes.push({id:Date.now(),name:gps.name,type,ore:type==='asteroid'?'Unknown':'—',x:gps.x,y:gps.y,z:gps.z,note:f.get('description')||gps.description||'Newly added local GPS entry.',cluster:'Unassigned'});modal.classList.add('hidden');e.target.reset();e.target.elements.type.value='station';renderList();draw()};
function nearbyDistance(km){return km<1?Math.round(km*1000)+' m':km.toLocaleString(undefined,{maximumFractionDigits:1})+' km'}
function nearestNodes(position,limit=3){return nodes.map(node=>({node,distance:Math.hypot(node.x-position.x,node.y-position.y,node.z-position.z)/1000})).sort((a,b)=>a.distance-b.distance).slice(0,limit)}
function nearestCluster(position){return clusters.map(cluster=>({cluster,distance:Math.hypot(position.x/1000-cluster.x,position.y/1000-cluster.y,position.z/1000-cluster.z)})).sort((a,b)=>a.distance-b.distance)[0]}

const positionModal=document.getElementById('positionModal');function openPositionModal(){document.getElementById('positionError').textContent='';document.getElementById('currentGps').value=currentPosition?`GPS:${currentPosition.name}:${currentPosition.x}:${currentPosition.y}:${currentPosition.z}:#FFF08BD2:`:'';positionModal.classList.remove('hidden');document.getElementById('currentGps').focus()}document.getElementById('closePositionModal').onclick=()=>positionModal.classList.add('hidden');document.getElementById('positionForm').onsubmit=e=>{e.preventDefault();const gps=parseGps(new FormData(e.target).get('gps')),error=document.getElementById('positionError');if(!gps){error.textContent='GPS format not recognized. Use GPS:Name:X:Y:Z:#COLOR:';return}currentPosition={name:gps.name,x:gps.x,y:gps.y,z:gps.z};positionModal.classList.add('hidden');returnToMainMap();renderCurrentPosition()};renderCurrentPosition();
const dbModal=document.getElementById('dbModal');document.getElementById('connectMysql').onclick=()=>dbModal.classList.remove('hidden');document.getElementById('closeDbModal').onclick=()=>dbModal.classList.add('hidden');document.getElementById('dbForm').onsubmit=async e=>{e.preventDefault();const form=e.target,error=document.getElementById('dbError'),button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Connecting…';error.textContent='';try{const body=Object.fromEntries(new FormData(form));body.port=Number(body.port);const response=await fetch('http://127.0.0.1:8765/api/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let result={};try{result=await response.json()}catch{}if(!response.ok||result.error)throw new Error(result.error||'Connection failed');dbModal.classList.add('hidden');document.getElementById('datasetStatus').textContent='MYSQL CONNECTED';await loadDatabase()}catch(err){error.textContent=err instanceof TypeError?'Cannot reach the local bridge. Start server.py, then try again.':err.message}finally{button.disabled=false;button.textContent='Connect and import GPS'}};
