function groupedGpsNodes(source){const entries=Array.isArray(source)?source:[];if(!autoGroupGps)return entries;const buckets=new Map();entries.forEach(node=>{const coded=codedGpsName(node.name);if(!coded)return;const baseKey=(node.cluster||'Unassigned')+'|'+normalizeCategory(node.type,node.ore)+'|'+coded.key,groups=buckets.get(baseKey)||[],group=groups.find(candidate=>{const first=candidate.members[0];return Math.hypot(node.x-first.x,node.y-first.y,node.z-first.z)<=AUTO_GROUP_RADIUS_METERS});if(group)group.members.push(node);else groups.push({key:baseKey+'|'+groups.length,base:coded.base,members:[node]});buckets.set(baseKey,groups)});return entries.map(node=>{const coded=codedGpsName(node.name);if(!coded)return node;const baseKey=(node.cluster||'Unassigned')+'|'+normalizeCategory(node.type,node.ore)+'|'+coded.key,group=(buckets.get(baseKey)||[]).find(candidate=>candidate.members.includes(node));if(!group||group.members.length<2||group.members[0]!==node)return group&&group.members.length>1?null:node;const materials=[];group.members.forEach(member=>{const material=codedGpsName(member.name)?.detail||'';if(material&&!materials.some(item=>item.toLowerCase()===material.toLowerCase()))materials.push(material)});const first=group.members[0];return{...first,id:'group:'+encodeURIComponent(group.key),name:group.base+(materials.length?' '+materials.join(' '):''),ore:materials.join(' · ')||first.ore,note:group.members.length+' GPS signals grouped within 1 km. Uses the first GPS location.',grouped:true,members:group.members,groupMaterials:materials}}).filter(Boolean)}
