const ROUTE_HAZARD_STORAGE='se-gps-route-hazards-v1';
const HAZARD_TYPES={danger:{label:'Danger',color:'#F07178'},pirate:{label:'Pirate patrol',color:'#F6A765'},gravity:{label:'Gravity well',color:'#9BA8FF'},nofly:{label:'No-fly zone',color:'#F08BD2'},caution:{label:'Caution',color:'#F6D570'}};
function routeHazardType(value){return HAZARD_TYPES[String(value||'').toLowerCase()]?String(value).toLowerCase():'danger'}
function normalizeRouteHazards(value){return(Array.isArray(value)?value:[]).filter(item=>item&&Number.isFinite(Number(item.x))&&Number.isFinite(Number(item.y))&&Number.isFinite(Number(item.z))).slice(0,100).map((item,index)=>({id:String(item.id||('hazard-'+index)),name:String(item.name||'Unnamed hazard').trim().slice(0,48)||'Unnamed hazard',type:routeHazardType(item.type),x:Number(item.x),y:Number(item.y),z:Number(item.z),radiusKm:Math.max(1,Math.min(250000,Number(item.radiusKm)||25))}))}
