var routeHazards=readRouteHazards(),activeResource='';
function hazardMeta(hazard){return HAZARD_TYPES[routeHazardType(hazard?.type)]}
function hazardColor(hazard){return hazardMeta(hazard).color}
function hazardGpsString(hazard){return'GPS:'+hazard.name+':'+hazard.x+':'+hazard.y+':'+hazard.z+':#FF'+hazardColor(hazard).slice(1)+':'}
function saveRouteHazards(){try{localStorage.setItem(ROUTE_HAZARD_STORAGE,JSON.stringify(routeHazards));queueAccountPreferencesSave();return true}catch{return false}}
function routeHazardId(){return(window.crypto&&typeof window.crypto.randomUUID==='function'?window.crypto.randomUUID():'hazard-'+Date.now()+'-'+Math.random().toString(16).slice(2))}
function hazardRadiusLabel(hazard){return Math.round(hazard.radiusKm).toLocaleString()+' km'}
function drawHazardRing(center,radius,axisA,axisB,color){ctx.beginPath();for(let step=0;step<=28;step++){const angle=step/28*Math.PI*2,point=project(center.x+radius*(axisA[0]*Math.cos(angle)+axisB[0]*Math.sin(angle)),center.y+radius*(axisA[1]*Math.cos(angle)+axisB[1]*Math.sin(angle)),center.z+radius*(axisA[2]*Math.cos(angle)+axisB[2]*Math.sin(angle)));if(step)ctx.lineTo(point.x,point.y);else ctx.moveTo(point.x,point.y)}ctx.strokeStyle=colorWithAlpha(color,.48);ctx.stroke()}
