function project(x,y,z){const center=projectionCenter;x-=center.x;y-=center.y;z-=center.z;const sx=Math.cos(yaw)*x-Math.sin(yaw)*z,sz=Math.sin(yaw)*x+Math.cos(yaw)*z,sy=Math.cos(pitch)*y-Math.sin(pitch)*sz,depth=Math.sin(pitch)*y+Math.cos(pitch)*sz,extent=projectionExtent,viewZoom=Math.max(.2,zoom),cameraDistance=extent*(5.6/Math.sqrt(viewZoom)),focalLength=extent*6.2,perspective=Math.max(.52,Math.min(2.35,focalLength/(cameraDistance+depth))),scale=Math.min(canvas.clientWidth,canvas.clientHeight)/(extent*2)*mapVisualScale();return{x:canvas.clientWidth/2+sx*scale*perspective+panX,y:canvas.clientHeight/2-sy*scale*perspective+panY,depth,perspective}}
