// A focused cluster is the inspection view, so every GPS signal stays named.
// The original renderer still handles screen-space label spacing.
const atlasBaseDrawNode=drawNode;
drawNode=function(node){atlasBaseDrawNode(focusedCluster?{...node,showLabel:true}:node)};
draw=function(){atlasBaseDraw();if(layerVisible('hazards'))drawRouteHazards()};
function setupHazardMapLayer(){mapLayerPanel.innerHTML='<span>MAP LAYERS</span>'+[['stars','Stars'],['grid','Grid planes'],['hazards','Route hazards'],['regions','Regions'],['clusters','Clusters'],['gps','GPS signals'],['position','My location']].map(item=>'<label class="map-layer-option"><span>'+item[1]+'</span><input type="checkbox" data-layer="'+item[0]+'"></label>').join('');renderMapLayers();mapLayerPanel.querySelectorAll('[data-layer]').forEach(input=>input.onchange=()=>{mapLayers[input.dataset.layer]=input.checked;saveMapLayers();renderMapLayers();clearRegionHover();draw()})}
function nodeResources(node){const raw=String(node?.ore||'').trim();if(!raw||raw==='—'||raw.toLowerCase()==='unknown')return[];return raw.split(/[;,|/]+/).map(value=>value.trim()).filter(value=>value&&value.toLowerCase()!=='unknown')}
function resourceCatalog(){const catalog=new Map();nodes.filter(node=>normalizeCategory(node.type,node.ore)==='asteroid').forEach(node=>nodeResources(node).forEach(resource=>catalog.set(resource,(catalog.get(resource)||0)+1)));return[...catalog].map(item=>({name:item[0],count:item[1]})).sort((a,b)=>a.name.localeCompare(b.name))}
function resourceMatches(){return activeResource?nodes.filter(node=>nodeResources(node).includes(activeResource)):[]}
function resourceNearest(){if(!currentPosition||!activeResource)return null;return resourceMatches().map(node=>({node,distance:Math.hypot(node.x-currentPosition.x,node.y-currentPosition.y,node.z-currentPosition.z)/1000})).sort((a,b)=>a.distance-b.distance||a.node.name.localeCompare(b.node.name))[0]||null}
function setResourceFilter(resource){activeResource=resource||'';if(activeResource){filter='asteroid';document.querySelectorAll('.filter').forEach(button=>button.classList.toggle('active',button.dataset.filter==='asteroid'))}invalidateVisible();renderList();draw()}
function renderResourceFinder(){const select=document.getElementById('resourceSelect'),count=document.getElementById('resourceCount'),hint=document.getElementById('resourceHint'),nearestButton=document.getElementById('resourceNearest');if(!select||!count||!hint||!nearestButton)return;const catalog=resourceCatalog();if(activeResource&&!catalog.some(item=>item.name===activeResource))activeResource='';select.innerHTML='<option value="">All resources</option>'+catalog.map(item=>'<option value="'+escapeHtml(item.name)+'">'+escapeHtml(item.name)+' ('+item.count+')</option>').join('');select.value=activeResource;const matches=resourceMatches(),closest=resourceNearest();count.textContent=String(activeResource?matches.length:catalog.length).padStart(2,'0');hint.textContent=!catalog.length?'No asteroid resources in the current atlas.':!activeResource?'Choose a resource to filter its asteroid GPS signals.':closest?matches.length+' signals · nearest '+closest.node.name+' at '+nearbyDistance(closest.distance)+'.':currentPosition?matches.length+' signals · no location available.':matches.length+' signals · set your location to find the nearest.';nearestButton.disabled=!closest;nearestButton.textContent=closest?'◎ Nearest':'◎ Nearest';select.onchange=()=>setResourceFilter(select.value);nearestButton.onclick=()=>{const result=resourceNearest();if(!result)return;const cluster=clusters.find(item=>item.name===result.node.cluster);if(cluster&&!focusedCluster)focusSector(cluster.name);select(result.node.id)};document.getElementById('clearResource').onclick=()=>setResourceFilter('')}
const atlasBaseRenderList=renderList;
