const hazardModal=document.getElementById('hazardModal'),hazardForm=document.getElementById('hazardForm');
function resetHazardEditor(){hazardForm.reset();document.getElementById('hazardId').value='';document.getElementById('hazardType').value='danger';document.getElementById('hazardRadius').value='25';document.getElementById('hazardError').textContent='';document.getElementById('saveHazard').textContent='＋ Add hazard';document.getElementById('cancelHazardEdit').hidden=true}
function openHazardEditor(hazard){document.getElementById('hazardId').value=hazard.id;document.getElementById('hazardName').value=hazard.name;document.getElementById('hazardGps').value=hazardGpsString(hazard);document.getElementById('hazardType').value=routeHazardType(hazard.type);document.getElementById('hazardRadius').value=hazard.radiusKm;document.getElementById('hazardError').textContent='';document.getElementById('saveHazard').textContent='Save hazard changes';document.getElementById('cancelHazardEdit').hidden=false;document.getElementById('hazardName').focus()}
function renderHazardList(){const list=document.getElementById('hazardList'),count=document.getElementById('hazardCount');if(!list||!count)return;count.textContent=String(routeHazards.length).padStart(2,'0');list.innerHTML=routeHazards.length?routeHazards.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(hazard=>'<article class="hazard-item" style="--hazard-color:'+hazardColor(hazard)+'"><div><strong>'+escapeHtml(hazard.name)+'</strong><small>'+escapeHtml(hazardMeta(hazard).label.toUpperCase())+' · '+hazardRadiusLabel(hazard)+'</small></div><div class="hazard-actions"><button type="button" data-hazard-edit="'+escapeHtml(hazard.id)+'">Edit</button><button type="button" class="hazard-delete" data-hazard-delete="'+escapeHtml(hazard.id)+'">Delete</button></div></article>').join(''):'<p class="hazard-empty">No route hazards saved.</p>';list.onclick=event=>{const edit=event.target.closest('[data-hazard-edit]'),remove=event.target.closest('[data-hazard-delete]'),id=(edit||remove)?.dataset.hazardEdit||(edit||remove)?.dataset.hazardDelete;if(!id)return;const hazard=routeHazards.find(item=>item.id===id);if(!hazard)return;if(edit){openHazardEditor(hazard);return}if(window.confirm('Delete hazard zone “'+hazard.name+'”?')){routeHazards=routeHazards.filter(item=>item.id!==id);saveRouteHazards();resetHazardEditor();renderHazardList();draw()}}}
