hazardForm.onsubmit=event=>{event.preventDefault();const form=new FormData(hazardForm),gps=parseGps(String(form.get('gps')||'')),name=String(form.get('name')||'').trim(),radius=Number(form.get('radius')),error=document.getElementById('hazardError');if(!name){error.textContent='A hazard name is required.';return}if(!gps){error.textContent='Paste a valid GPS string for the centre.';return}if(!Number.isFinite(radius)||radius<1||radius>250000){error.textContent='Radius must be between 1 and 250,000 km.';return}const id=document.getElementById('hazardId').value||routeHazardId(),hazard={id,name:name.slice(0,48),type:routeHazardType(form.get('type')),x:gps.x,y:gps.y,z:gps.z,radiusKm:radius};routeHazards=routeHazards.some(item=>item.id===id)?routeHazards.map(item=>item.id===id?hazard:item):[...routeHazards,hazard];saveRouteHazards();resetHazardEditor();renderHazardList();draw()};
