function regionStatisticsMarkup(region){const members=nodes.filter(node=>region.clusters.some(cluster=>cluster.name===node.cluster)),asteroids=members.filter(node=>normalizeCategory(node.type,node.ore)==='asteroid'),resources=new Set(asteroids.flatMap(nodeResources)),dated=members.map(node=>({node,time:Date.parse(node.createdAt||'')})).filter(item=>Number.isFinite(item.time)).sort((a,b)=>b.time-a.time),newest=dated[0]?.node,span=Math.max(0,Math.round((region.r||0)*2));const stat=(label,value,detail='')=>'<div><small>'+label+'</small><b>'+escapeHtml(String(value))+'</b>'+(detail?'<em>'+escapeHtml(detail)+'</em>':'')+'</div>';return'<section class="region-statistics"><span>REGION STATISTICS</span><div class="region-stat-grid">'+stat('CLUSTERS',region.clusters.length)+stat('GPS SIGNALS',members.length)+stat('ASTEROIDS',asteroids.length)+stat('RESOURCES',resources.size)+stat('MAPPED SPAN',span.toLocaleString()+' km')+stat('NEWEST GPS',newest?formatGpsTimestamp(newest.createdAt):'—',newest?newest.name:'No timestamps available')+'</div></section>'}
const atlasBaseRenderRegionDetails=renderRegionDetails;
