const RESOURCE_ALIAS_GROUPS=[['fe','iron','ironore'],['ni','nickel','nickelore'],['co','cobalt','cobaltore'],['si','silicon','siliconore'],['mg','magnesium','magnesiumore'],['ag','silver','silverore'],['au','gold','goldore'],['pt','platinum','platinumore'],['u','uranium','uraniumore'],['ice','waterice'],['stone','rock'],['scrap','scrapmetal']];
const RESOURCE_ALIAS_LOOKUP=Object.fromEntries(RESOURCE_ALIAS_GROUPS.flatMap(group=>group.map(alias=>[alias,group])));
function normalizedResourceTerm(value){return String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'')}
function resourceSearchMatches(node,value){const term=normalizedResourceTerm(value),aliases=RESOURCE_ALIAS_LOOKUP[term],nameTokens=String(node?.name||'').split(/[^A-Za-z0-9]+/);return Boolean(aliases&&[...nodeResources(node),...nameTokens].some(resource=>aliases.includes(normalizedResourceTerm(resource))))}
visible=function(){if(visibleCache)return visibleCache;visibleCache=nodes.filter(node=>{const category=normalizeCategory(node.type,node.ore),hay=(node.name+' '+node.ore+' '+node.cluster+' '+categoryInfo(category).label).toLowerCase(),inRegion=!focusedRegion||focusedRegion.clusters.some(cluster=>cluster.name===node.cluster),matchesSearch=!query||hay.includes(query)||resourceSearchMatches(node,query);return(!focusedCluster||node.cluster===focusedCluster.name)&&inRegion&&(filter==='all'||category===filter)&&(!activeResource||nodeResources(node).includes(activeResource))&&matchesSearch});return visibleCache};
let sharedNotesSequence=0;
function sharedNotesSection(type,key){const sectionId='sharedNotes-'+(++sharedNotesSequence),canAdd=Boolean(window.atlasCanEdit?.());return'<section class="shared-notes" id="'+sectionId+'"><div class="shared-notes-heading"><span>SHARED NOTES</span><b>··</b></div><div class="shared-notes-list"><p class="shared-notes-empty">Loading shared notes…</p></div>'+(canAdd?'<form class="shared-note-form"><textarea maxlength="1000" placeholder="Add a note for the atlas…"></textarea><p class="shared-note-error"></p><button class="mini-btn" type="submit">＋ Add shared note</button></form>':'<p class="shared-notes-readonly">Trusted access is required to add notes.</p>')+'</section>'}
function sharedNoteMarkup(note){return'<article class="shared-note"><p>'+escapeHtml(note.body||'').replace(/\n/g,'<br>')+'</p><small>'+escapeHtml(note.author_name||'Unknown')+' · '+escapeHtml(formatGpsTimestamp(note.created_at||''))+'</small></article>'}
async function loadSharedNotes(type,key,sectionId){const section=document.getElementById(sectionId);if(!section)return;const list=section.querySelector('.shared-notes-list'),count=section.querySelector('.shared-notes-heading b');try{const params=new URLSearchParams({entity_type:type,entity_key:String(key)}),response=await fetch('http://127.0.0.1:8765/api/notes?'+params.toString()),payload=await response.json();if(!response.ok||payload.error)throw new Error(payload.error||'Could not load notes');const notes=Array.isArray(payload.notes)?payload.notes:[];count.textContent=String(notes.length).padStart(2,'0');list.innerHTML=notes.length?notes.map(sharedNoteMarkup).join(''):'<p class="shared-notes-empty">No shared notes yet.</p>'}catch(error){count.textContent='--';list.innerHTML='<p class="shared-notes-empty">Notes are unavailable.</p>'}}
function appendSharedNotes(type,key){if(key===undefined||key===null||key==='')return;const card=document.getElementById('selectedCard');if(!card||card.querySelector('.shared-notes'))return;card.insertAdjacentHTML('beforeend',sharedNotesSection(type,key));const section=card.querySelector('.shared-notes:last-child');if(!section)return;const form=section.querySelector('.shared-note-form'),sectionId=section.id;if(form){form.onsubmit=async event=>{event.preventDefault();const input=form.querySelector('textarea'),error=form.querySelector('.shared-note-error'),button=form.querySelector('button'),body=input.value.trim();if(!body){error.textContent='Write a note first.';return}button.disabled=true;error.textContent='';try{const response=await fetch('http://127.0.0.1:8765/api/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({entity_type:type,entity_key:String(key),body})}),payload=await response.json();if(!response.ok||payload.error)throw new Error(payload.error||'Could not add note');input.value='';await loadSharedNotes(type,key,sectionId)}catch(err){error.textContent=err.message}finally{button.disabled=false}}}loadSharedNotes(type,key,sectionId)}
