async function readDatabaseRevision(){const response=await fetch('http://127.0.0.1:8765/api/data/revision');const payload=await response.json();if(!response.ok||!payload.revision)throw new Error(payload.error||'Could not check the database revision');return payload.revision}
const atlasFullLoadDatabase=loadDatabase;
let databaseRevision='',databaseRevisionCheckInFlight=false;
loadDatabase=async function(options={}){const preserve=Boolean(options.preserve);if(!preserve){const result=await atlasFullLoadDatabase(options);if(document.getElementById('datasetStatus').textContent==='MYSQL CONNECTED'){try{databaseRevision=await readDatabaseRevision()}catch{databaseRevision=''}}return result}if(databaseSyncInFlight||databaseRevisionCheckInFlight)return;databaseRevisionCheckInFlight=true;try{const revision=await readDatabaseRevision();if(revision===databaseRevision){markDatabaseSynced();return}const result=await atlasFullLoadDatabase(options);if(document.getElementById('datasetStatus').textContent==='MYSQL CONNECTED')databaseRevision=revision;return result}catch{return atlasFullLoadDatabase(options)}finally{databaseRevisionCheckInFlight=false}};
