async function loadDatabase(options={}){const preserve=Boolean(options.preserve),state=preserve?currentMapState():null;if(databaseSyncInFlight)return;databaseSyncInFlight=true;try{const response=await fetch('http://127.0.0.1:8765/api/data');if(!response.ok)throw new Error('Database bridge returned HTTP '+response.status);const data=await response.json();if(data.error)throw new Error(data.error);const fingerprint=syncFingerprint(data);if(preserve&&fingerprint===databaseFingerprint){markDatabaseSynced();return}if(!Array.isArray(data.entries))throw new Error('Database bridge returned invalid GPS data');nodes.splice(0,nodes.length,...data.entries.map(entry=>{const ore=entry.ore_type||'Unknown',kind=(entry.location_type||'').toLowerCase();return{id:entry.id,name:entry.name,type:normalizeCategory(kind,ore),ore,x:Number(entry.x),y:Number(entry.y),z:Number(entry.z),note:entry.description||'Imported from MySQL.',cluster:entry.cluster_name||'Unassigned',visibility:entry.visibility||'user',createdAt:entry.created_at||''}}));clusters.splice(0,clusters.length,...(Array.isArray(data.clusters)?data.clusters:[]).map(cluster=>({name:cluster.name,x:Number(cluster.center_x)/1000,y:Number(cluster.center_y)/1000,z:Number(cluster.center_z)/1000,r:10,visibility:cluster.visibility||'user',regionKey:cluster.region_key||'',regionVisibility:cluster.region_visibility||'user'})));clusters.forEach(cluster=>{const distances=nodes.filter(node=>node.cluster===cluster.name).map(node=>{const point=world(node);return Math.hypot(point.x-cluster.x,point.y-cluster.y,point.z-cluster.z)});cluster.r=Math.max(8,...distances)*1.35});deriveRegions();databaseFingerprint=fingerprint;restoreMapState(state);refreshMapControls();markDatabaseSynced();renderSectors();renderList();renderCurrentPosition();if(selected)select(selected.id);else if(focusedCluster)renderClusterDetails(focusedCluster);else if(focusedRegion)renderRegionDetails(focusedRegion);else showEmptySelection();draw()}catch(error){document.getElementById('datasetStatus').textContent='MYSQL OFFLINE';document.getElementById('datasetStatus').title=error.message}finally{databaseSyncInFlight=false}}
